#!/usr/bin/env python3
"""Write docs/functions.md and docs/files.md from the last build.

Usage: make && python3 tools/gen_docs.py

Both lists come from build/dd64.map and dd64.yaml, so they match the current
build. Rerun after decompiling or renaming anything.
"""
import os
import re

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
ROM_BASE = 0x80000400 - 0x1000
TEXT_END = 0x8007ADD0  # start of the RSP microcode

# What the cleaned-up files hold. Generated files are described by their range.
FILE_NOTES = {
    "src/main/boot.c": "Boot: idle and main threads, video mode, game init",
    "src/romfile.c": "Read-only file over the zippeddata.zip ROM area (fopen/fread/fseek style)",
    "src/heap.c": "First-fit heap with an address-sorted free list",
    "src/pool.c": "Fixed-size block pools",
    "src/mem.c": "Allocations from the main heap (Mem_Alloc, Mem_Free)",
    "src/libultra/string.c": "strlen, memcpy",
}


def state_of(path):
    if path.startswith("asm/"):
        return "asm"
    if path.startswith("src/auto/"):
        return "C (generated)"
    return "C"


def parse_map():
    """(vram, name, object path) for every function-like text symbol in the main segment."""
    syms = []
    cur = None
    in_text = False
    for line in open(os.path.join(ROOT, "build", "dd64.map")):
        m = re.match(r"^ (\.\w+)\s+0x([0-9a-f]+)\s+0x([0-9a-f]+)\s+build/(\S+)\.o$", line)
        if m:
            in_text = m.group(1) == ".text"
            cur = m.group(4)
            continue
        if line.startswith(" .") or line.startswith(" *"):
            in_text = False
            continue
        m = re.match(r"^\s+0x([0-9a-f]{8})\s+([A-Za-z_]\w*)$", line)
        if m and in_text and cur:
            addr = int(m.group(1), 16)
            name = m.group(2)
            if 0x80000400 <= addr < TEXT_END and not name.endswith((".NON_MATCHING", "_ROM_START", "_ROM_END", "_VRAM", "_VRAM_END")):
                syms.append((addr, name, cur))
    # one entry per address; prefer a real name over a func_ placeholder
    best = {}
    for addr, name, obj in syms:
        if addr not in best or (best[addr][0].startswith("func_") and not name.startswith("func_")):
            best[addr] = (name, obj)
    return sorted((a, n, o) for a, (n, o) in best.items())


def source_of(obj):
    """build path of an object -> the file it was built from."""
    if obj.startswith("asm/"):
        return obj  # asm/XXXX.s
    return obj  # src/....c


def asm_sizes():
    """Size of every function still in asm/, from splat's nonmatching lines."""
    sizes = {}
    for d, _, files in os.walk(os.path.join(ROOT, "asm")):
        for f in files:
            if f.endswith(".s"):
                for m in re.finditer(r"^nonmatching (\w+), 0x([0-9A-F]+)", open(os.path.join(d, f)).read(), re.M):
                    sizes[m.group(1)] = int(m.group(2), 16)
    return sizes


def main():
    funcs = parse_map()
    sizes = asm_sizes()
    rows = []
    for i, (addr, name, obj) in enumerate(funcs):
        end = funcs[i + 1][0] if i + 1 < len(funcs) else TEXT_END
        size = end - addr
        if sizes.get(name) == 4 or (size <= 4 and name.startswith("func_")):
            continue  # a lone nop: padding after the last function of a file
        rows.append((addr, size, name, source_of(obj)))

    # functions.md
    out = ["# Function list", "",
           "Every function in the main code segment, in address order. Generated by `tools/gen_docs.py` from the last build.", "",
           "State: **C** is cleaned up, **C (generated)** matches but still has placeholder types, **asm** is not decompiled yet. Sizes include any padding after a function.", "",
           "| VRAM | ROM | Size | Name | File | State |", "|---|---|---|---|---|---|"]
    for addr, size, name, src in rows:
        out.append(f"| `{addr:08X}` | `{addr - ROM_BASE:06X}` | {size:#x} | `{name}` | `{src}` | {state_of(src)} |")
    open(os.path.join(ROOT, "docs", "functions.md"), "w").write("\n".join(out) + "\n")

    # files.md: group consecutive functions by file
    files = []
    for addr, size, name, src in rows:
        if files and files[-1]["src"] == src:
            f = files[-1]
        else:
            f = {"src": src, "start": addr, "end": addr, "count": 0, "names": []}
            files.append(f)
        f["end"] = addr + size
        f["count"] += 1
        if not name.startswith("func_"):
            f["names"].append(name)

    done = sum(f["count"] for f in files if not f["src"].startswith("asm/"))
    total = sum(f["count"] for f in files)
    out = ["# File list", "",
           "The main code segment split into source files, in address order. Generated by `tools/gen_docs.py` from the last build and `dd64.yaml`.", "",
           f"{done} of {total} functions are in C.", "",
           "Files in `src/auto/` and `asm/` are named after their ROM offset; their real boundaries are not known yet. "
           "A lone `nop` after a function usually marks the end of an original source file.", "",
           "| ROM | VRAM | Size | File | State | Functions | Named functions or notes |", "|---|---|---|---|---|---|---|"]
    for f in files:
        note = FILE_NOTES.get(f["src"])
        if not note:
            names = f["names"]
            note = ", ".join(f"`{n}`" for n in names[:6]) + (f" and {len(names) - 6} more" if len(names) > 6 else "")
        out.append(f"| `{f['start'] - ROM_BASE:06X}` | `{f['start']:08X}` | {f['end'] - f['start']:#x} | `{f['src']}` | "
                   f"{state_of(f['src'])} | {f['count']} | {note} |")
    open(os.path.join(ROOT, "docs", "files.md"), "w").write("\n".join(out) + "\n")
    print(f"{len(rows)} functions, {len(files)} files")


if __name__ == "__main__":
    main()
